{"command": "python3 -c "from rich.prompt import Prompt; print('Test 1: Case Sensitive (Should fail if input is lowercase)')
try:
    Prompt.ask('Enter choice', choices=['Paul', 'Jessica'], case_sensitive=True)
except Exception as e:
    print(f'Caught expected error: {e}')

print('\nTest 2: Case Insensitive (Should pass if input is lowercase)')
try:
    Prompt.ask('Enter choice', choices=['Paul', 'Jessica'], case_sensitive=False)
except Exception as e:
    print(f'Caught unexpected error: {e}')

print('\nTest 3: Case Insensitive (Should pass if input is mixed case)')
try:
    Prompt.ask('Enter choice', choices=['Paul', 'Jessica'], case_sensitive=False)
except Exception as e:
    print(f'Caught unexpected error: {e}')
""}

